\begin{enumerate}
\item A red-black tree storing \ensuremath{\ensuremath{\ensuremath{\mathit{n}}}} values has height at most $2\log \ensuremath{\ensuremath{\ensuremath{\mathit{n}}}}$.
\item The \ensuremath{\ensuremath{\mathrm{add}(\ensuremath{\mathit{x}})}} and \ensuremath{\ensuremath{\mathrm{remove}(\ensuremath{\mathit{x}})}} operations on a red-black tree run
   in $O(\log \ensuremath{\ensuremath{\ensuremath{\mathit{n}}}})$ \emph{worst-case} time.
\item The amortized number of rotations performed during an \ensuremath{\ensuremath{\mathrm{add}(\ensuremath{\mathit{x}})}}
   or \ensuremath{\ensuremath{\mathrm{remove}(\ensuremath{\mathit{x}})}} operation is constant.
\end{enumerate}

\footnote{Note that skiplists and
treaps also have this property in the expected sense. See
Exercises~\ref{exc:skiplist-changes} and \ref{exc:treap-rotates}.}

\begin{prp}[height]
  All leaves have the same depth.
\end{prp}

\begin{prp}[degree]
  Every internal node has 2, 3, or 4 children.
\end{prp}

\begin{lem}\lemlabel{twofour-height}
  A 2-4 tree with \ensuremath{\ensuremath{\ensuremath{\mathit{n}}}} leaves has height at most $\log \ensuremath{\ensuremath{\ensuremath{\mathit{n}}}}$.
\end{lem}

