\begin{prp}[left-leaning]\prplabel{left-leaning}\prplabel{redblack-last}
  \index{left-leaning property}%
  At any node \ensuremath{\ensuremath{\ensuremath{\mathit{u}}}}, if \ensuremath{\ensuremath{\ensuremath{\mathit{u}}.\ensuremath{\mathit{left}}}} is black, then \ensuremath{\ensuremath{\ensuremath{\mathit{u}}.\ensuremath{\mathit{right}}}} is black.
\end{prp}

