\begin{thm}
  A RedBlackTree implements the SSet interface and
  supports the operations \ensuremath{\ensuremath{\mathrm{add}(\ensuremath{\mathit{x}})}}, \ensuremath{\ensuremath{\mathrm{remove}(\ensuremath{\mathit{x}})}}, and \ensuremath{\ensuremath{\mathrm{find}(\ensuremath{\mathit{x}})}} in $O(\log
  \ensuremath{\ensuremath{\ensuremath{\mathit{n}}}})$ worst-case time per operation.
\end{thm}

\begin{thm}\thmlabel{redblack-amortized}
  Beginning with an empty RedBlackTree, any sequence of $m$
  \ensuremath{\ensuremath{\mathrm{add}(\ensuremath{\mathit{x}})}} and \ensuremath{\ensuremath{\mathrm{remove}(\ensuremath{\mathit{x}})}} operations results in a total of $O(m)$
  time spent during all calls \ensuremath{\ensuremath{\mathrm{add\_fixup}(\ensuremath{\mathit{u}})}} and \ensuremath{\ensuremath{\mathrm{remove\_fixup}(\ensuremath{\mathit{u}})}}. 
\end{thm}

\footnote{See the proofs of
\lemref{dualarraydeque-amortized} and \lemref{selist-amortized} for
other applications of the potential method.}

