\begin{exc}
  Suppose a 2-4 tree, $T$, has $\ensuremath{\ensuremath{\ensuremath{\mathit{n}}}}_\ell$ leaves and $\ensuremath{\ensuremath{\ensuremath{\mathit{n}}}}_i$ internal nodes.
  \begin{enumerate}
    \item What is the minimum value of $\ensuremath{\ensuremath{\ensuremath{\mathit{n}}}}_i$, as a function of $\ensuremath{\ensuremath{\ensuremath{\mathit{n}}}}_\ell$?
    \item What is the maximum value of $\ensuremath{\ensuremath{\ensuremath{\mathit{n}}}}_i$, as a function of $\ensuremath{\ensuremath{\ensuremath{\mathit{n}}}}_\ell$?
    \item If $T'$ is a red-black tree that represents $T$, then how many red
     nodes does $T'$ have?
  \end{enumerate}
\end{exc}

